function snapshot(){const {params,preset,view,...arrangement}=state;return {state:JSON.stringify(arrangement),selection:[...selected]}}
function stash(){history.push(snapshot());if(history.length>100)history.shift();redoHistory=[];if($('undo'))$('undo').disabled=false;if($('redo'))$('redo').disabled=true}
function restoreEdit(entry){stop();velocityGesture=false;state={...state,...JSON.parse(entry.state)};selected=new Set(entry.selection.filter(id=>state.notes.some(n=>n.id===id)));refresh();persist()}
function undoEdit(){if(!history.length)return;redoHistory.push(snapshot());restoreEdit(history.pop())}
function redoEdit(){if(!redoHistory.length)return;history.push(snapshot());restoreEdit(redoHistory.pop())}

function persist(){try{localStorage.setItem('drift-project',JSON.stringify(state));$('saveStatus').textContent='Saved on this device'}catch{$('saveStatus').textContent='Use Save project to keep your work'}}
