function renderControls(){let html='';for(const group of controlGroups){html+='<details class="sound-group" data-group="'+group.start+'" '+(openGroups.has(group.start)?'open':'')+'><summary>'+group.name+'</summary><div class="group-controls">';if(group.start===2)html+='<label class="layer-select">WAVE <select id="layerWave"><option value="sine">Sine</option><option value="triangle">Triangle</option><option value="sawtooth">Saw</option><option value="square">Square</option></select></label><label class="layer-select">REGISTER <select id="layerOctave"><option value="-1">−1 octave</option><option value="0">Unison</option><option value="1">+1 octave</option></select></label>';for(const [k,label,min,max,step,unit] of specs.slice(group.start,group.end)){state.params[k]=clamp(state.params[k],min,max);html+='<div class="control"><div class="control-head"><label for="p-'+k+'">'+label+'</label><output id="o-'+k+'">'+valText(k,state.params[k],unit)+'</output></div><input id="p-'+k+'" type="range" min="'+min+'" max="'+max+'" step="'+step+'" value="'+state.params[k]+'"></div>'}html+='</div></details>'}$('controls').innerHTML=html;document.querySelectorAll('.sound-group').forEach(d=>d.ontoggle=()=>d.open?openGroups.add(+d.dataset.group):openGroups.delete(+d.dataset.group));for(const [k,,,,,unit]of specs){$('p-'+k).oninput=e=>{state.params[k]=+e.target.value;$('o-'+k).textContent=valText(k,state.params[k],unit);customSound();synth?.set({[k]:state.params[k]});persist()}}for(const k of ['layerWave','layerOctave']){$(k).value=state.params[k];$(k).onchange=e=>{state.params[k]=k==='layerOctave'?+e.target.value:e.target.value;customSound();synth?.set({[k]:state.params[k]});persist()}}$('wave').value=state.params.wave;$('preset').value=state.preset;$('soundDesc').textContent=presets[state.preset]?.desc||'Your own corner of the atmosphere.'}
