$('preset').onchange=e=>{state.preset=e.target.value;state.params={...state.params,...presets[state.preset]};delete state.params.desc;renderControls();synth?.set(state.params);persist()};$('wave').onchange=e=>{state.params.wave=e.target.value;customSound();synth?.set({wave:state.params.wave});persist()};
