function renderChords(){const box=$('chords');box.innerHTML='';state.chords.forEach((c,i)=>{let b=document.createElement('button');b.className='chord';b.innerHTML='<small>BAR '+(Math.floor(c.start/4)+1)+' · BEAT '+(c.start%4+1)+' / '+c.length+' BEATS</small><strong>'+pcName(c.root)+suffix[c.quality]+'</strong><span>'+chordNotes(c).map(noteName).join(' · ')+'</span><em>'+transitionText(c.transition)+(PadHarmony.compatible(c,state.key,state.scale)?'':' · outside scale')+'</em>';b.onclick=()=>{editChord=i;$('root').value=c.root;$('quality').value=c.quality;$('inversion').value=c.inversion;$('chordVoicingNote').textContent=c.voicing?'Auto voicing: '+chordNotes(c).map(noteName).join(' · '):'Root/inversion voicing';$('chordInKey').textContent=PadHarmony.compatible(c,state.key,state.scale)?'All chord tones are in the selected scale.':'This chord contains tones outside the selected scale.';$('chordStart').max=state.bars;$('chordBars').max=state.bars*4;$('chordStart').value=Math.floor(c.start/4)+1;$('chordBeat').value=c.start%4+1;$('chordBars').value=c.length;$('chordTransition').value=c.transition;updateChordTransition();$('chordDialog').showModal()};box.append(b)});if(!state.chords.length){let b=document.createElement('button');b.className='chord';b.textContent='+ Add chord';b.onclick=()=>$('addChord').click();box.append(b)}}
